import { cookies } from 'next/headers'

// Stores the user's notification preference in a cookie.
// Swap this for your real persistence layer (e.g. a user record in your DB).
const COOKIE_NAME = 'notifications-enabled'

export async function getNotificationPreference(): Promise<boolean> {
  const cookieStore = await cookies()
  return cookieStore.get(COOKIE_NAME)?.value === 'true'
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  const cookieStore = await cookies()
  cookieStore.set(COOKIE_NAME, String(enabled), {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: 60 * 60 * 24 * 365,
  })
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
